create type public.app_role as enum ('citizen','municipal');
create type public.incident_status as enum ('pendiente','en_revision','en_atencion','resuelto','rechazado');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null check (char_length(full_name) between 3 and 120), role public.app_role not null default 'citizen', district text check (district in ('Los Olivos','Comas','San Martín de Porres','Independencia')), check (role <> 'municipal' or district is not null), created_at timestamptz not null default now());
create table public.pets (id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id) on delete cascade, name text not null check (char_length(name) between 2 and 80), species text not null check (species in ('Perro','Gato','Otro')), breed text check (char_length(breed)<=80), age integer not null check (age between 0 and 40), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.incidents (id uuid primary key default gen_random_uuid(), reporter_id uuid not null references public.profiles(id) on delete cascade, district text not null check (district in ('Los Olivos','Comas','San Martín de Porres','Independencia')), address text not null check (char_length(address) between 5 and 180), description text not null check (char_length(description) between 15 and 2000), status public.incident_status not null default 'pendiente', observation text check (char_length(observation)<=1000), check (status <> 'rechazado' or char_length(trim(coalesce(observation,'')))>=5), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.incident_status_history (id uuid primary key default gen_random_uuid(), incident_id uuid not null references public.incidents(id) on delete cascade, changed_by uuid references public.profiles(id), old_status public.incident_status, new_status public.incident_status not null, observation text, created_at timestamptz not null default now());
create index pets_owner_idx on public.pets(owner_id);
create index incidents_reporter_idx on public.incidents(reporter_id,created_at desc);
create index incidents_district_status_idx on public.incidents(district,status,created_at desc);
create index history_incident_idx on public.incident_status_history(incident_id,created_at desc);
create function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$ declare supplied_name text; begin supplied_name=trim(left(coalesce(new.raw_user_meta_data->>'full_name',''),120)); insert into public.profiles(id,full_name,role) values(new.id,case when char_length(supplied_name)>=3 then supplied_name else 'Ciudadano' end,'citizen'); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.new_profile();
create function public.is_municipal_for(d text) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='municipal' and district=d) $$;
create function public.guard_profile() returns trigger language plpgsql as $$ begin if current_user='authenticated' and (new.role is distinct from old.role or new.district is distinct from old.district) then raise exception 'Role and district cannot be changed by the user'; end if; return new; end $$;
create trigger guard_profile_update before update on public.profiles for each row execute function public.guard_profile();
create function public.guard_incident() returns trigger language plpgsql as $$ begin if current_user='authenticated' then if new.reporter_id is distinct from old.reporter_id or new.district is distinct from old.district or new.address is distinct from old.address or new.description is distinct from old.description then raise exception 'Only status and observation may be changed'; end if; if not public.is_municipal_for(old.district) then raise exception 'Municipal scope required'; end if; end if; new.updated_at=now(); return new; end $$;
create trigger guard_incident_update before update on public.incidents for each row execute function public.guard_incident();
create function public.record_incident_status() returns trigger language plpgsql security definer set search_path=public as $$ begin if tg_op='INSERT' then insert into public.incident_status_history(incident_id,changed_by,new_status) values(new.id,new.reporter_id,new.status); elsif new.status is distinct from old.status or new.observation is distinct from old.observation then insert into public.incident_status_history(incident_id,changed_by,old_status,new_status,observation) values(new.id,auth.uid(),old.status,new.status,new.observation); end if; return new; end $$;
create trigger incident_history_insert after insert on public.incidents for each row execute function public.record_incident_status();
create trigger incident_history_update after update on public.incidents for each row execute function public.record_incident_status();
alter table public.profiles enable row level security;
alter table public.pets enable row level security;
alter table public.incidents enable row level security;
alter table public.incident_status_history enable row level security;
create policy profiles_select on public.profiles for select to authenticated using (id=auth.uid());
create policy profiles_update on public.profiles for update to authenticated using (id=auth.uid()) with check (id=auth.uid());
create policy pets_select on public.pets for select to authenticated using (owner_id=auth.uid());
create policy pets_insert on public.pets for insert to authenticated with check (owner_id=auth.uid() and exists(select 1 from public.profiles where id=auth.uid() and role='citizen'));
create policy pets_update on public.pets for update to authenticated using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy incidents_select on public.incidents for select to authenticated using (reporter_id=auth.uid() or public.is_municipal_for(district));
create policy incidents_insert on public.incidents for insert to authenticated with check (reporter_id=auth.uid() and status='pendiente' and observation is null and exists(select 1 from public.profiles where id=auth.uid() and role='citizen'));
create policy incidents_update on public.incidents for update to authenticated using (public.is_municipal_for(district)) with check (public.is_municipal_for(district));
create policy history_select on public.incident_status_history for select to authenticated using (exists(select 1 from public.incidents where id=incident_id));
